import { ArrowRight } from 'lucide-react'
import { useCatalog } from '../lib/catalog-context'
import { latestUpdateGroups } from '../lib/selectors'
import { navigate } from '../lib/router'
import { cx, formatDate, formatViews, seriesHref, chapterHref } from '../lib/utils'
import type { Series, WeekDay } from '../types'

const DAYS: WeekDay[] = [
  'Monday',
  'Tuesday',
  'Wednesday',
  'Thursday',
  'Friday',
  'Saturday',
  'Sunday',
]

const DAY_CAP = 12

const link =
  (to: string) =>
  (e: React.MouseEvent): void => {
    if (e.metaKey || e.ctrlKey) return
    e.preventDefault()
    navigate(to)
  }

/** Monday-first index of today, 0–6. */
function todayIndex(): number {
  return (new Date().getDay() + 6) % 7
}

function latestChapterNumber(s: Series): number | null {
  const last = s.chapters[s.chapters.length - 1]
  return last ? last.number : null
}

export default function Calendar() {
  const { series, loading } = useCatalog()

  if (loading) {
    return (
      <main className="animate-fade-up">
        <div
          className="border-b border-line"
          style={{
            background: 'linear-gradient(115deg, hsl(20 30% 14%) 0%, hsl(30 28% 26%) 100%)',
          }}
        >
          <div className="mx-auto max-w-[1240px] px-4 py-12 sm:px-6 lg:px-8">
            <div className="h-3 w-28 animate-pulse rounded bg-white/20" />
            <div className="mt-4 h-10 w-80 max-w-full animate-pulse rounded bg-white/20" />
            <div className="mt-4 h-4 w-full max-w-xl animate-pulse rounded bg-white/15" />
          </div>
        </div>
        <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {DAYS.map((d) => (
              <div
                key={d}
                className="rounded-[14px] border border-line bg-paper p-4"
              >
                <div className="h-4 w-20 animate-pulse rounded bg-paper-3/60" />
                <div className="mt-4 space-y-2.5">
                  {Array.from({ length: 5 }).map((_, i) => (
                    <div key={i} className="h-3.5 w-full animate-pulse rounded bg-paper-3/60" />
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>
    )
  }

  const today = todayIndex()
  const groups = latestUpdateGroups(series, 12)

  return (
    <main className="animate-fade-up">
      {/* Banner */}
      <div
        className="border-b border-line"
        style={{
          background: 'linear-gradient(115deg, hsl(20 30% 14%) 0%, hsl(30 28% 26%) 100%)',
        }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <button
            onClick={() => navigate('/updates')}
            className="mb-6 inline-flex items-center gap-1.5 text-sm font-semibold text-white/70 transition-colors hover:text-white"
          >
            <span className="text-base leading-none">←</span> Latest Updates
          </button>
          <div className="eyebrow text-accent">Release Calendar</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">
            Manhwa Release Calendar
          </h1>
          <p className="mt-3 max-w-xl text-white/70">
            When new chapters drop — every series grouped by its weekly release day, so you know
            exactly when to come back.
          </p>
          <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-white/60">
            <span>
              <strong className="text-white">{series.length}</strong> series
            </span>
            <span>
              <strong className="text-white">{DAYS[today]}</strong> today
            </span>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
        {/* Weekly grid */}
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {DAYS.map((day, i) => {
            const rows = series
              .filter((s) => s.schedule === day)
              .sort((a, b) => b.weeklyViews - a.weeklyViews)
            const visible = rows.slice(0, DAY_CAP)
            const hidden = rows.length - visible.length
            const isToday = i === today
            return (
              <section
                key={day}
                className={cx(
                  'rounded-[14px] border bg-paper p-4',
                  isToday ? 'border-accent ring-1 ring-accent/30' : 'border-line',
                )}
              >
                <div className="flex items-center justify-between gap-2">
                  <h2 className={cx('text-sm font-extrabold tracking-tight', isToday && 'text-accent')}>
                    {day}
                  </h2>
                  {isToday && (
                    <span className="rounded-full bg-accent/12 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-accent">
                      Today
                    </span>
                  )}
                  <span className="ml-auto text-xs tabular-nums text-ink-faint">{rows.length}</span>
                </div>

                {visible.length === 0 ? (
                  <p className="mt-3 text-xs text-ink-faint">No scheduled releases.</p>
                ) : (
                  <ul className="mt-3 space-y-1">
                    {visible.map((s) => {
                      const ch = latestChapterNumber(s)
                      return (
                        <li key={s.id}>
                          <a
                            href={`${seriesHref(s)}`}
                            onClick={link(`${seriesHref(s)}`)}
                            className="group flex items-center gap-2 rounded-md px-1.5 py-1 transition-colors hover:bg-paper-2"
                          >
                            <span
                              className={cx(
                                'h-1.5 w-1.5 shrink-0 rounded-full',
                                s.status === 'Ongoing' ? 'bg-accent' : 'bg-line-strong',
                              )}
                            />
                            <span className="line-clamp-1 min-w-0 flex-1 text-xs font-semibold text-ink transition-colors group-hover:text-accent">
                              {s.title}
                            </span>
                            {ch !== null && (
                              <span className="shrink-0 text-[10px] tabular-nums text-ink-faint">
                                Ch. {ch}
                              </span>
                            )}
                          </a>
                        </li>
                      )
                    })}
                  </ul>
                )}

                {hidden > 0 && (
                  <div className="mt-2 px-1.5 text-[10px] font-medium text-ink-faint">
                    +{hidden} more
                  </div>
                )}
              </section>
            )
          })}
        </div>

        {/* Recently released */}
        <section className="mt-14">
          <div className="eyebrow mb-4 text-accent">Recently released</div>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {groups.map((group) => (
              <div key={group.key} className="rounded-[14px] border border-line bg-paper p-4">
                <div className="flex items-baseline justify-between">
                  <h3 className="text-sm font-extrabold tracking-tight">{group.label}</h3>
                  <span className="text-xs text-ink-faint">{group.rows.length} updates</span>
                </div>
                <ul className="mt-3 space-y-2.5">
                  {group.rows.map(({ series: s, chapters }) => (
                    <li key={s.id}>
                      <div className="flex items-baseline justify-between gap-3">
                        <a
                          href={`${seriesHref(s)}`}
                          onClick={link(`${seriesHref(s)}`)}
                          className="line-clamp-1 text-sm font-bold tracking-tight transition-colors hover:text-accent"
                        >
                          {s.title}
                        </a>
                        <span className="shrink-0 text-[10px] font-medium uppercase tracking-wide text-ink-faint">
                          {formatViews(s.weeklyViews)} weekly
                        </span>
                      </div>
                      <div className="mt-0.5 flex items-baseline justify-between gap-3">
                        <a
                          href={chapterHref(s, chapters[0].number)}
                          onClick={link(chapterHref(s, chapters[0].number))}
                          className="line-clamp-1 text-xs font-semibold text-ink-soft transition-colors hover:text-accent"
                        >
                          <span className="text-accent">→</span> Chapter {chapters[0].number}
                        </a>
                        <span className="shrink-0 text-[10px] tabular-nums text-ink-faint">
                          {formatDate(chapters[0].releaseDate)}
                        </span>
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
          <div className="mt-8 text-center">
            <a
              href="/updates"
              onClick={link('/updates')}
              className="group inline-flex items-center gap-2 rounded-full border border-ink/25 px-5 py-2.5 text-sm font-semibold text-ink transition-all hover:border-ink hover:bg-ink hover:text-paper"
            >
              All latest updates
              <ArrowRight
                width={16}
                height={16}
                className="transition-transform group-hover:translate-x-0.5"
              />
            </a>
          </div>
        </section>
      </div>
    </main>
  )
}
